import{_ as a,o as d,c as r,a2 as e}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Правила Межплоскостной Навигации","description":"","frontmatter":{},"headers":[],"relativePath":"ru/81-位面穿梭规则.md","filePath":"ru/81-位面穿梭规则.md","lastUpdated":1789183869000}'),i={name:"ru/81-位面穿梭规则.md"};function l(o,t,h,n,s,p){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="правила-межплоскостнои-навигации" tabindex="-1">Правила Межплоскостной Навигации <a class="header-anchor" href="#правила-межплоскостнои-навигации" aria-label="Permalink to &quot;Правила Межплоскостной Навигации&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>81</td></tr><tr><td>Модуль</td><td>Межплоскостное взаимодействие и правила времени</td></tr><tr><td>Ключевые слова</td><td>межплоскостная навигация, разрешения на навигацию, энергетические пороги, калибровка Якоря, профилактика и контроль загрязнения</td></tr></tbody></table><h2 id="i-правовое-положение-навигации" tabindex="-1">I. Правовое положение навигации <a class="header-anchor" href="#i-правовое-положение-навигации" aria-label="Permalink to &quot;I. Правовое положение навигации&quot;">​</a></h2><p>Межплоскостная навигация обозначает поведение, при котором отдельное существо или группа существ пересекает барьер законов и переходит из одной плоскости в другую техническими средствами или культивационными способностями. В правовой системе Симбиотической Цивилизации Якоря межплоскостная навигация относится к «особо опасному поведению» и подлежит строгому управлению разрешениями и контролю процесса. Статья 47 Симбиотической Конституции гласит: «Ни одна организация и ни одно лицо не вправе без разрешения совершать межплоскостную навигацию, а также использовать межплоскостную навигацию для деятельности по хищению, вмешательству или загрязнению цивилизации других плоскостей».</p><p>Фундаментальная причина строгого контроля навигации в том, что само поведение навигации может оказать множественное воздействие на целевую плоскость: возмущение законов, впрыскивание энергии, загрязнение сознания, вторжение микроорганизмов и культурное вмешательство. Эти воздействия в лучшем случае вызывают локальные аномалии целевой плоскости, а в худшем могут изменить траекторию её цивилизационной эволюции или даже привести к обрушению законов. Поэтому центральная цель правил навигации — «удерживать внешнее воздействие навигации в приемлемом пороге».</p><h2 id="ii-иерархическая-система-разрешении-на-навигацию" tabindex="-1">II. Иерархическая система разрешений на навигацию <a class="header-anchor" href="#ii-иерархическая-система-разрешении-на-навигацию" aria-label="Permalink to &quot;II. Иерархическая система разрешений на навигацию&quot;">​</a></h2><p>Вселенная Хэнъюань применяет иерархическую систему разрешений на межплоскостную навигацию, разделяющую разрешения на четыре уровня по цели навигации, типу целевой плоскости и квалификации навигатора:</p><table tabindex="0"><thead><tr><th>Уровень разрешения</th><th>Применимый сценарий</th><th>Орган утверждения</th><th>Срок действия</th><th>Дополнительные условия</th></tr></thead><tbody><tr><td>Уровень A (Археологическое наблюдение)</td><td>Чисто наблюдательная археология, без какого-либо физического контакта</td><td>Управление Плоскостей</td><td>Разовое задание</td><td>Обязательно использовать схему Зеркало Репликации + изолированное пространство</td></tr><tr><td>Уровень B (Академический обмен)</td><td>Ограниченный обмен знаниями с цивилизацией целевой плоскости</td><td>Управление Плоскостей + Министерство Культуры</td><td>Не более одного года</td><td>Должно быть подписано соглашение о взаимном невмешательстве</td></tr><tr><td>Уровень C (Ресурсное сотрудничество)</td><td>Сотрудничество в ресурсах и технологиях на основе равенства и взаимной выгоды</td><td>Специальное утверждение Собрания Якоря</td><td>Не более трёх лет</td><td>Требуется согласие цивилизации целевой плоскости</td></tr><tr><td>Уровень D (Экстренное вмешательство)</td><td>Гуманитарное вмешательство при кризисе уровня вымирания целевой плоскости</td><td>Экстренная резолюция Собрания Якоря</td><td>Период кризиса</td><td>После вмешательства требуется полный отчёт</td></tr></tbody></table><p>Разрешения на навигацию любого уровня запрещают: хищение изначальной энергии целевой плоскости, принудительное распространение идеологии своей плоскости, генетические или сознательные модификации без согласия, создание постоянных военных баз в целевой плоскости и любые формы колониального господства.</p><h2 id="iii-технические-требования-и-энергетические-пороги-навигации" tabindex="-1">III. Технические требования и энергетические пороги навигации <a class="header-anchor" href="#iii-технические-требования-и-энергетические-пороги-навигации" aria-label="Permalink to &quot;III. Технические требования и энергетические пороги навигации&quot;">​</a></h2><p>Межплоскостная навигация должна удовлетворять строгим техническим условиям. Во-первых, навигатор должен обладать культивацией выше третьего уровня (Стадия Хуакун) «системы регулирования пространственных правовых принципов» или находиться в соответствующем стандартам межплоскостном навигационном средстве. Во-вторых, и точка отправления, и точка прибытия должны иметь Якорь для калибровки координат; слепая навигация без позиционирования по Якорю строго запрещена.</p><p>Энергопотребление процесса навигации пропорционально прочности барьера законов целевой плоскости. Вселенная Хэнъюань установила стандартизированную «таблицу энергетических порогов навигации». Минимальная энергия, необходимая для навигации к различным типам плоскостей, следующая:</p><ul><li>Плоскость Материальной Доминанты: 1000 стандартных единиц энергии</li><li>Плоскость Проявленной Энергии: 5000 стандартных единиц энергии</li><li>Плоскость Доминанты Сознания: 20 000 стандартных единиц энергии</li><li>Плоскость Разломов Законов: 50 000 стандартных единиц энергии (при этом уровень успеха ниже 30 %)</li><li>Плоскость, Близкая к Изначальной: теоретическое значение свыше 100 000; успешных записей пока нет</li></ul><p>Энергия навигации должна перевозиться самим навигатором или средством; извлечение энергии из целевой плоскости для процесса навигации запрещено. Это положение призвано предотвратить энергетическое хищение целевой плоскости навигацией.</p><h2 id="iv-профилактика-и-контроль-загрязнения-в-процессе-навигации" tabindex="-1">IV. Профилактика и контроль загрязнения в процессе навигации <a class="header-anchor" href="#iv-профилактика-и-контроль-загрязнения-в-процессе-навигации" aria-label="Permalink to &quot;IV. Профилактика и контроль загрязнения в процессе навигации&quot;">​</a></h2><p>Один из наибольших рисков межплоскостной навигации — «межплоскостное загрязнение», включающее биологическое загрязнение (перенос микроорганизмов своей плоскости в целевую), энергетическое загрязнение (влияние остатков энергии своей плоскости на законы целевой) и загрязнение сознания (влияние колебаний сознания навигатора на область сознания целевой плоскости).</p><p>Для профилактики и контроля загрязнения все навигаторы обязаны пройти «процедуру очищения в три уровня» перед отправлением:</p><ol><li><strong>Биологическое очищение</strong>: проведение 72-часового скрининга и устранения микроорганизмов в изолированном пространстве для гарантии отсутствия патогенов своей плоскости.</li><li><strong>Энергетическое очищение</strong>: приведение энергетической частоты навигатора в диапазон, совместимый с целевой плоскостью, с помощью устройства калибровки Якоря, снижая реакции энергетического отталкивания.</li><li><strong>Очищение сознания</strong>: прохождение тренировки экранирования сознания для гарантии, что во время навигации не будут активно излучаться колебания мыслей, способные вмешаться в область сознания целевой плоскости.</li></ol><p>Кроме того, сфера активности навигатора в целевой плоскости строго ограничена «зоной, определённой разрешением на навигацию», неавторизованное распространение запрещено. После возвращения в свою плоскость навигатор обязан снова пройти карантинное наблюдение сроком не менее 30 дней в пересчёте на скорость времени целевой плоскости.</p><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Правила межплоскостной навигации — первая линия обороны безопасности межплоскостного взаимодействия. Через тройной механизм классификации разрешений, технических порогов и профилактики и контроля загрязнения они обеспечивают, что навигация всегда движется по пути «низкого воздействия, прослеживаемости и подотчётности». Конечная цель правил — не ограничивать обмен между цивилизациями, а сделать так, чтобы обмен происходил симбиотическим образом, а не хищническим.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>80-位面理论与分类 (Теория Плоскостей и Классификация)</li><li>88-跨位面伦理准则 (Межплоскостные Этические Нормы)</li><li>62-空间法理技术实现 (Техническая Реализация Пространственных Правовых Принципов)</li></ul>',23)])])}const u=a(i,[["render",l]]);export{c as __pageData,u as default};
